+    // #18848: atuin generates ctrl-r and up-arrow both named "atuin".
+    let merged = merge(vec![
+        binding("atuin", "control", "char_r"),
+        binding("atuin", "none", "up"),
+    ]);
+    assert_eq!(merged.iter().filter(|b| b.name == "atuin").count(), 2);
